+  if (cmd === 'git') {
+    let i = 1;
+    while (argv[i]?.startsWith('-')) i += ['-C', '-c', '--git-dir', '--work-tree', '--namespace'].includes(argv[i]) ? 2 : 1;
+    const sub = argv[i];
